-- Phase 1 baseline schema: identity, RBAC, refresh tokens, audit trail, news.
-- Conventions:
--   * uuid primary keys, generated by the application (Hibernate UUID generator)
--   * timestamptz everywhere, application writes UTC instants
--   * app_ prefix on identity tables to avoid reserved words (user, role)
--   * audit_log deliberately has no foreign keys so the trail survives deletions

CREATE TABLE app_permission (
    code        varchar(64)  NOT NULL,
    description varchar(255) NOT NULL,
    CONSTRAINT pk_app_permission PRIMARY KEY (code)
);

CREATE TABLE app_role (
    id          uuid         NOT NULL,
    code        varchar(64)  NOT NULL,
    name        varchar(120) NOT NULL,
    description varchar(255),
    system_role boolean      NOT NULL DEFAULT false,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_app_role PRIMARY KEY (id),
    CONSTRAINT uq_app_role_code UNIQUE (code)
);

CREATE TABLE app_role_permission (
    role_id         uuid        NOT NULL,
    permission_code varchar(64) NOT NULL,
    CONSTRAINT pk_app_role_permission PRIMARY KEY (role_id, permission_code),
    CONSTRAINT fk_app_role_permission_role FOREIGN KEY (role_id)
        REFERENCES app_role (id) ON DELETE CASCADE,
    CONSTRAINT fk_app_role_permission_permission FOREIGN KEY (permission_code)
        REFERENCES app_permission (code) ON DELETE CASCADE
);

CREATE TABLE app_user (
    id                    uuid         NOT NULL,
    email                 varchar(320) NOT NULL,
    password_hash         varchar(100) NOT NULL,
    display_name          varchar(120) NOT NULL,
    enabled               boolean      NOT NULL DEFAULT true,
    failed_login_attempts integer      NOT NULL DEFAULT 0,
    locked_until          timestamptz,
    last_login_at         timestamptz,
    password_changed_at   timestamptz,
    must_change_password   boolean     NOT NULL DEFAULT false,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    updated_at            timestamptz  NOT NULL DEFAULT now(),
    version               bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_app_user PRIMARY KEY (id)
);

-- Case-insensitive uniqueness without the citext extension.
CREATE UNIQUE INDEX uq_app_user_email_lower ON app_user (lower(email));

CREATE TABLE app_user_role (
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    CONSTRAINT pk_app_user_role PRIMARY KEY (user_id, role_id),
    CONSTRAINT fk_app_user_role_user FOREIGN KEY (user_id)
        REFERENCES app_user (id) ON DELETE CASCADE,
    CONSTRAINT fk_app_user_role_role FOREIGN KEY (role_id)
        REFERENCES app_role (id) ON DELETE CASCADE
);

CREATE TABLE refresh_token (
    id                  uuid         NOT NULL,
    user_id             uuid         NOT NULL,
    token_hash          varchar(64)  NOT NULL,
    issued_at           timestamptz  NOT NULL DEFAULT now(),
    expires_at          timestamptz  NOT NULL,
    revoked_at          timestamptz,
    revoked_reason      varchar(32),
    replaced_by_token_id uuid,
    ip_address          varchar(64),
    user_agent          varchar(512),
    CONSTRAINT pk_refresh_token PRIMARY KEY (id),
    CONSTRAINT uq_refresh_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_token_user FOREIGN KEY (user_id)
        REFERENCES app_user (id) ON DELETE CASCADE
);

CREATE INDEX idx_refresh_token_user ON refresh_token (user_id);
CREATE INDEX idx_refresh_token_expires_at ON refresh_token (expires_at);

CREATE TABLE audit_log (
    id            uuid        NOT NULL,
    occurred_at   timestamptz NOT NULL DEFAULT now(),
    action        varchar(64) NOT NULL,
    outcome       varchar(16) NOT NULL DEFAULT 'SUCCESS',
    entity_type   varchar(64),
    entity_id     varchar(128),
    summary       varchar(512),
    actor_user_id uuid,
    actor_email   varchar(320),
    ip_address    varchar(64),
    user_agent    varchar(512),
    before_state  jsonb,
    after_state   jsonb,
    CONSTRAINT pk_audit_log PRIMARY KEY (id),
    CONSTRAINT ck_audit_log_outcome CHECK (outcome IN ('SUCCESS', 'FAILURE'))
);

CREATE INDEX idx_audit_log_occurred_at ON audit_log (occurred_at DESC);
CREATE INDEX idx_audit_log_entity ON audit_log (entity_type, entity_id);
CREATE INDEX idx_audit_log_action ON audit_log (action);
CREATE INDEX idx_audit_log_actor ON audit_log (actor_user_id);

CREATE TABLE news_category (
    id          uuid         NOT NULL,
    slug        varchar(120) NOT NULL,
    name        varchar(120) NOT NULL,
    description varchar(500),
    sort_order  integer      NOT NULL DEFAULT 0,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_news_category PRIMARY KEY (id),
    CONSTRAINT uq_news_category_slug UNIQUE (slug)
);

CREATE TABLE news_article (
    id                 uuid         NOT NULL,
    slug               varchar(200) NOT NULL,
    title              varchar(300) NOT NULL,
    subtitle           varchar(400),
    summary            varchar(1000),
    body               text         NOT NULL,
    body_format        varchar(16)  NOT NULL DEFAULT 'HTML',
    status             varchar(20)  NOT NULL DEFAULT 'DRAFT',
    category_id        uuid,
    author_user_id     uuid,
    author_display_name varchar(120),
    cover_image_url    varchar(2048),
    cover_image_alt    varchar(300),
    meta_title         varchar(200),
    meta_description   varchar(400),
    canonical_path     varchar(500),
    og_title           varchar(200),
    og_description     varchar(400),
    og_image_url       varchar(2048),
    robots             varchar(64)  NOT NULL DEFAULT 'index,follow',
    keywords           varchar(500),
    featured           boolean      NOT NULL DEFAULT false,
    published_at       timestamptz,
    archived_at        timestamptz,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    version            bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_news_article PRIMARY KEY (id),
    CONSTRAINT uq_news_article_slug UNIQUE (slug),
    CONSTRAINT ck_news_article_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
    CONSTRAINT ck_news_article_published_at CHECK (status <> 'PUBLISHED' OR published_at IS NOT NULL),
    CONSTRAINT ck_news_article_body_format CHECK (body_format IN ('HTML', 'MARKDOWN', 'PLAIN')),
    CONSTRAINT fk_news_article_category FOREIGN KEY (category_id)
        REFERENCES news_category (id) ON DELETE SET NULL,
    CONSTRAINT fk_news_article_author FOREIGN KEY (author_user_id)
        REFERENCES app_user (id) ON DELETE SET NULL
);

-- Public listing predicate: status = 'PUBLISHED' AND published_at <= now()
CREATE INDEX idx_news_article_public ON news_article (status, published_at DESC);
CREATE INDEX idx_news_article_category ON news_article (category_id);
CREATE INDEX idx_news_article_canonical_path ON news_article (canonical_path);
